<script>
document.querySelector('[data-add-order-line]')?.addEventListener('click', () => {
    const container = document.getElementById('order-lines');
    const index = container.querySelectorAll('.order-line').length;
    const row = container.querySelector('.order-line').cloneNode(true);
    row.querySelectorAll('[name]').forEach((field) => {
        field.name = field.name.replace('lines[0]', `lines[${index}]`);
        if (field.tagName === 'SELECT') field.selectedIndex = 0;
        else field.value = field.name.endsWith('[quantity]') ? '1' : '';
    });
    container.appendChild(row);
});
</script>
